              <!-- شعار التطبيق -->
              <div class="text-center pt-8">
                <v-avatar size="80" class="logo-avatar mb-4">
                  <v-icon size="50" color="white">mdi-chat</v-icon>
                </v-avatar>
                <h2 class="app-title">{{ $t('app.name') || 'Glass Book' }}</h2>
                <p class="app-subtitle">{{ $t('app.tagline') || 'Connect with friends' }}</p>
              </div>

              <!-- الهيدر مع التبويبات -->
              <v-toolbar color="transparent" flat>
                <v-tabs
                  v-model="activeTab"
