                <!-- رسالة النجاح -->
                <v-alert
                  v-if="successMessage"
                  type="success"
                  dismissible
                  class="mb-4"
                  @input="clearSuccess"
                >
                  {{ successMessage }}
                </v-alert>

                <!-- نموذج تسجيل الدخول -->
                <v-form
                  ref="loginForm"
                  v-model="formValid"
                  @submit.prevent="login"
                  lazy-validation
                >
                  <!-- حقل البريد الإلكتروني -->
                  <v-text-field
                    v-model="email"
                    :label="$t('auth.Email')"
                    :rules="emailRules"
                    name="email"
                    prepend-inner-icon="mdi-email-outline"
                    type="email"
                    required
                    outlined
                    dense
                    class="mb-2"
                    @keyup.enter="login"
                    :loading="loading"
                  ></v-text-field>

                  <!-- حقل كلمة المرور -->
                  <v-text-field
                    v-model="password"
                    :label="$t('auth.Password')"
                    :rules="passwordRules"
                    name="password"
                    :prepend-inner-icon="showPassword ? 'mdi-lock-open' : 'mdi-lock'"
                    :append-icon="showPassword ? 'mdi-eye-off' : 'mdi-eye'"
                    @click:append="showPassword = !showPassword"
                    :type="showPassword ? 'text' : 'password'"
                    required
                    outlined
                    dense
                    class="mb-4"
                    @keyup.enter="login"
                    :loading="loading"
                  ></v-text-field>

                  <!-- خيارات إضافية -->
                  <!-- <v-row align="center" justify="space-between" class="mb-4">
                    <v-col cols="6">
                      <v-checkbox
                        v-model="rememberMe"
