<script>
import CountryFlag from "vue-country-flag";
import { mapActions, mapGetters } from "vuex";
import LogoutDialog from "@/components/LogoutDialog.vue";

export default {
  name: "LoginPage",
  
  components: {
    CountryFlag,
    LogoutDialog
  },

  data: () => ({
    // نموذج البيانات
    email: "",
    password: "",
    rememberMe: false,
    
    // حالة الواجهة
    activeTab: 0,
    showPassword: false,
    formValid: false,
    loading: false,
    showLogoutDialog: false,
    
    // اللغات المدعومة
    selectedLanguage: "en",
    languages: [
      { code: "en", name: "English", flag: "gb" },
      { code: "ar", name: "العربية", flag: "sa" }
    ],
    
    // قواعد التحقق
    emailRules: [
      v => !!v || "Email is required",
      v => /.+@.+\..+/.test(v) || "Email must be valid"
    ],
    passwordRules: [
      v => !!v || "Password is required",
      v => v.length >= 6 || "Password must be at least 6 characters"
    ],
    
    tabs: [
      { value: "Login", icon: "mdi-login" },
      { value: "signup", icon: "mdi-account-plus" }
    ]
  }),

  computed: {
    ...mapGetters({
      isAuthenticated: "auth/isAuthenticated",
      authError: "auth/error",
      authSuccess: "auth/success",
      getAuthAfterLogin: "getAuthAfterLogin"
    }),

    errorMessage() {
      return this.authError;
    },

    successMessage() {
      return this.authSuccess;
    }
  },

  watch: {
    // تحديث اللغة المحفوظة
    selectedLanguage(val) {
      localStorage.setItem("locale", val);
    },

    // توجيه المستخدم إذا كان مسجلاً
    isAuthenticated(val) {
      if (val) {
        this.$router.push("/posts");
      }
    }
  },

  created() {
    console.log("getAuthAfterLogin: ", this.getAuthAfterLogin)
    // استرجاع اللغة المحفوظة
    const savedLocale = localStorage.getItem("locale") || "en";
    this.selectedLanguage = savedLocale;
    this.$i18n.locale = savedLocale;
    
    // استرجاع البريد الإلكتروني المحفوظ
    const savedEmail = localStorage.getItem("rememberedEmail");
    if (savedEmail) {
      this.email = savedEmail;
      this.rememberMe = true;
    }
  },

  methods: {
     login() {
      this.$store.dispatch("login", {
        email: this.email,
        password: this.password,
      });
    },
    ...mapActions({
      loginAction: "auth/login",
      logoutAction: "auth/logout",
      clearAuthMessages: "auth/clearMessages"
    }),

    // تسجيل الدخول
    // async login() {
    //   if (this.$refs.loginForm.validate()) {
    //     this.loading = true;
    //     this.clearAuthMessages();

    //     try {
    //       await this.loginAction({
    //         email: this.email,
    //         password: this.password
    //       });

    //       // حفظ البريد الإلكتروني إذا اختار المستخدم
    //       if (this.rememberMe) {
    //         localStorage.setItem("rememberedEmail", this.email);
    //       } else {
    //         localStorage.removeItem("rememberedEmail");
    //       }

    //       // رسالة نجاح
    //       this.$toast?.success(this.$t('auth.loginSuccess'), {
    //         position: "top-right",
    //         duration: 3000
    //       });

    //     } catch (error) {
    //       console.error("Login error:", error);
    //       this.$toast?.error(this.$t('auth.loginError'), {
    //         position: "top-right",
    //         duration: 5000
    //       });
    //     } finally {
    //       this.loading = false;
    //     }
    //   }
    // },

    // تغيير اللغة
    changeLanguage(locale) {
      this.$i18n.locale = locale;
      this.selectedLanguage = locale;
      localStorage.setItem("locale", locale);
      
      // تحديث اتجاه الصفحة للعربية
      if (locale === "ar") {
        document.documentElement.setAttribute("dir", "rtl");
        document.body.classList.add("rtl");
      } else {
        document.documentElement.setAttribute("dir", "ltr");
        document.body.classList.remove("rtl");
      }
      
      this.$toast?.info(this.$t('auth.languageChanged'), {
        position: "top-right",
        duration: 2000
      });
    },

    // التنقل إلى صفحة التسجيل
    navigateToSignup() {
      this.$router.push("/signup");
    },

    // نسيان كلمة المرور
    forgotPassword() {
      if (this.email) {
        this.$router.push({
          name: "forgot-password",
          query: { email: this.email }
        });
      } else {
        this.$router.push("/forgot-password");
      }
    },

    // تسجيل الدخول الاجتماعي
    async socialLogin(provider) {
      this.loading = true;
      try {
        // تنفيذ تسجيل الدخول الاجتماعي
        await this.$store.dispatch(`auth/socialLogin`, { provider });
      } catch (error) {
        console.error(`${provider} login error:`, error);
      } finally {
        this.loading = false;
      }
    },

    // مسح رسائل الخطأ
    clearError() {
      this.clearAuthMessages();
    },

    // مسح رسائل النجاح
    clearSuccess() {
      this.clearAuthMessages();
    },

    // تأكيد تسجيل الخروج
    async confirmLogout() {
      this.showLogoutDialog = false;
      await this.logoutAction();
      this.$toast?.info(this.$t('auth.logoutSuccess'));
    }
  },

  beforeDestroy() {
    this.clearAuthMessages();
  }
};
</script>

